import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"mini-clash-course/glossary.md","filePath":"mini-clash-course/docs/glossary.md"}'),o={name:"mini-clash-course/glossary.md"};function s(n,t,l,i,c,P){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书术语按中文词条排列，每条一句话大白话定义；正文中每章首教的术语以「术语（英文）——解释」的形态就地展开，本表是集中翻查的那一份。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>正向代理</td><td>forward proxy</td><td>替客户端去访问服务器的中间人——你把请求交给它，它替你跑腿，目标网站只看到代理。</td></tr><tr><td>反向代理</td><td>reverse proxy</td><td>替服务器接收请求的中间人——用户只看到它，看不到后面真正的服务器（与正向代理方向相反，本课只做对照）。</td></tr><tr><td>系统代理</td><td>system proxy</td><td>操作系统级的一个开关：应用「自愿」读取它并把流量交给代理——不读它的应用就不走代理。</td></tr><tr><td>socket</td><td>socket</td><td>程序里代表一条 TCP 连接的对象——可以往里写字节、从里读字节、关掉它。</td></tr><tr><td>TCP 连接</td><td>TCP connection</td><td>两台机器之间先「拨号接通」再双向传字节、传完「挂断」的一条可靠通道。</td></tr><tr><td>端口</td><td>port</td><td>同一台机器上区分不同服务的房间号——IP 找到楼，端口找到房间。</td></tr><tr><td>回环地址</td><td>loopback address</td><td>127.0.0.1——「自己连自己」的内部地址，本课全部实验都在它上面跑，不出机器。</td></tr><tr><td>字节流</td><td>byte stream</td><td>TCP 给你的只是先后到达的一串字节，没有「消息边界」——切分要靠协议自己约定。</td></tr><tr><td>HTTP 报文</td><td>HTTP message</td><td>HTTP 通信的基本信件：信封（请求行/状态行 + 头部）+ 信纸（正文），按固定格式拼的字节。</td></tr><tr><td>请求行</td><td>request line</td><td>HTTP 请求的第一行：方法 + 目标 + 版本，如 GET <a href="http://a.com/" target="_blank" rel="noreferrer">http://a.com/</a> HTTP/1.1。</td></tr><tr><td>绝对地址形式</td><td>absolute-form</td><td>走代理时浏览器把请求行里的目标写成完整 URL（含 <a href="http://xn--eqrt2g" target="_blank" rel="noreferrer">http://域名</a>）——这是「告诉代理去哪」的信号。</td></tr><tr><td>CONNECT 隧道</td><td>CONNECT tunnel</td><td>HTTPS 走代理的办法：先让代理拨通目标，之后代理只当双向透传的管道，看不到加密内容。</td></tr><tr><td>SOCKS5</td><td>SOCKS Protocol Version 5</td><td>一个字节级的代理协议：先握手协商认证方式，再报目标地址，成功后透传任意字节。</td></tr><tr><td>大端序</td><td>big-endian</td><td>网络字节序：多字节数字「高位在前」的排法，如端口 80 写成 00 50。</td></tr><tr><td>字节协议</td><td>binary protocol</td><td>报文里没有「行」也没有分隔符、只有位置的一种协议——第几个字节是什么意思，全靠双方约定的表，任何字节值都合法出现、永远不需要转义。</td></tr><tr><td>目标地址类型</td><td>ATYP</td><td>SOCKS5 报文里声明目标地址形态的一个字节：1=IPv4、3=域名、4=IPv6。</td></tr><tr><td>两跳链路</td><td>two-hop chain</td><td>浏览器→本地代理是第一跳，本地代理→远端服务器是第二跳，目标网站只见远端服务器。</td></tr><tr><td>中继</td><td>relay</td><td>把两条 socket 对接起来、双向搬运字节的操作——代理数据面的主体。</td></tr><tr><td>帧</td><td>frame</td><td>自定义链路上的一段定界数据单元：头部写清长度，后面跟载荷，字节流因此有了边界。</td></tr><tr><td>机密性</td><td>confidentiality</td><td>加密要防的第一件事：除了持有密钥的人，谁也读不懂内容。</td></tr><tr><td>威胁模型</td><td>threat model</td><td>一张先说清「防谁、防什么、不防什么」的清单——不先画清单就谈加密，等于不知道防谁就开始买锁。</td></tr><tr><td>真实性</td><td>authenticity</td><td>加密要防的第三件事：证明这份密文确实出自持有钥匙的一方，不是中间人整封塞进来的假货。</td></tr><tr><td>完整性</td><td>integrity</td><td>加密要防的第二件事：内容在途中被改过一个字节，接收方都能发现并拒收。</td></tr><tr><td>认证加密</td><td>AEAD</td><td>同时做到加密+防篡改的现代加密方式：先验「火漆」再解密，验不过整段作废。</td></tr><tr><td>AES-GCM</td><td>AES-GCM</td><td>最常用的 AEAD 具体算法：AES 加密配 GCM 校验，Node.js crypto 内建。</td></tr><tr><td>随机数 nonce</td><td>nonce</td><td>AEAD 每次加密都要喂的「一次性编号」——同一段话加密两次密文不同，全靠它；重复使用是灾难。</td></tr><tr><td>盐</td><td>salt</td><td>每次会话随机生成的公开字节串——掺进密钥派生，让每条连接的密钥都不同，旧密文不被攒起来统一破解。</td></tr><tr><td>密钥派生</td><td>key derivation / HKDF</td><td>不直接拿密码当密钥，而是用密码+盐按标准步骤（HKDF）现配一把本会话密钥。</td></tr><tr><td>长度前缀分块</td><td>length-prefixed chunking</td><td>把字节流切成小块、每块先发「加密后的长度」再发「加密后的内容」——既恢复边界又防篡改长度。</td></tr><tr><td>规则引擎</td><td>rule engine</td><td>Clash 的分流大脑：拿目标（域名/IP）按配置的规则顺序逐条试，命中即决定走直连还是代理。</td></tr><tr><td>域名后缀规则</td><td>DOMAIN-SUFFIX</td><td>「以某域名结尾就走这条线」的规则，如 DOMAIN-SUFFIX,google.com 匹配 mail.google.com。</td></tr><tr><td>网段规则</td><td>IP-CIDR</td><td>按目标 IP 所在网段匹配的规则，如 192.168.0.0/16 匹配 192.168.x.x 全部地址。</td></tr><tr><td>IP 地址与 CIDR</td><td>IP address &amp; CIDR</td><td>IP 地址是 32 位编号的点分写法（每段 8 位）；CIDR 在它后面加斜杠前缀长度，如 /24 表示前 24 位是网段——刀口想落在哪一位都行。</td></tr><tr><td>兜底规则</td><td>MATCH</td><td>规则表的最后一条「其余全部」——前面都没命中时按它走，Clash 里通常写作 MATCH,DIRECT。</td></tr><tr><td>DNS</td><td>Domain Name System</td><td>把域名翻译成 IP 的电话簿系统——应用连网前通常先查它。</td></tr><tr><td>A 记录</td><td>A record</td><td>DNS 电话簿里「域名→IPv4 地址」的那一行。</td></tr><tr><td>DNS 污染</td><td>DNS poisoning</td><td>查询被半路截胡、塞回一个假 IP——浏览器拿着假门牌当然连不上。</td></tr><tr><td>DNS 泄露</td><td>DNS leak</td><td>DNS 查询本身是明文的：链路上每个中转都看得见你要访问哪个域名——哪怕后续连接全走加密。</td></tr><tr><td>fake-ip</td><td>fake-ip</td><td>Clash 的一招：DNS 查询不真去查，先发一个保留网段的假 IP 应急，同时把真域名记在账上，连接时再还原。</td></tr><tr><td>TUN 虚拟网卡</td><td>TUN device</td><td>操作系统里一根「虚拟网线」：整机流量先流进它，交给用户态程序处理——系统代理罩不住的应用也逃不掉。</td></tr><tr><td>五元组</td><td>5-tuple</td><td>识别一条 TCP 连接的五项信息：源 IP、源端口、目的 IP、目的端口、协议——代理进程靠它把一包包字节归回各自的连接。</td></tr><tr><td>IP 头部</td><td>IP header</td><td>每个 IP 包开头 20 字节左右的固定格式元数据：版本、总长、源/目的 IP 等。</td></tr><tr><td>报文段</td><td>TCP segment</td><td>TCP 层的包：头部（端口、序号、标志位）+ 载荷，多个段按序号重组成字节流。</td></tr><tr><td>声明式配置</td><td>declarative config</td><td>只写「要什么」不写「怎么做的」的配置文件——Clash 的 YAML 就是它（本课用 JSON 教同构语义）。</td></tr><tr><td>代理组</td><td>proxy group</td><td>把若干节点打包成一个可切换出口的虚拟节点——应用永远只见组，组内选谁由策略定。</td></tr><tr><td>自动测速组</td><td>url-test group</td><td>一类代理组策略：定期对组内节点发探测请求，谁延迟低选谁。</td></tr><tr><td>延迟探测</td><td>latency probe</td><td>给节点发一个小请求并掐表——衡量节点「快不快」的标准动作。</td></tr><tr><td>直连</td><td>DIRECT</td><td>Clash 里的特殊出站：不走任何代理节点，本机直接连目标。</td></tr></tbody></table>',3)])])}const T=d(o,[["render",s]]);export{p as __pageData,T as default};
